import { test, expect } from '@playwright/test';

test.describe('Responsive Layout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display layout in a single column on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 600, height: 800 });
    const layout = await page.getByRole('main');
    expect(await layout.evaluate(el => getComputedStyle(el).gridTemplateColumns)).toBe('1fr');
  });

  test('should display layout in a two-column grid on tablet', async ({ page }) => {
    await page.setViewportSize({ width: 800, height: 1280 });
    const layout = await page.getByRole('main');
    expect(await layout.evaluate(el => getComputedStyle(el).gridTemplateColumns)).toBe('repeat(2, 1fr)');
  });
});
